<script lang="ts">import {onMount} from 'svelte';import QRCode from 'qrcode';import type {Invoice} from '$lib/types';let {invoice}= $props<{invoice:Invoice}>();let qr=$state(''),remaining=$state(''),copied=$state(false);function update(){const ms=Math.max(0,new Date(invoice.expiresAt).getTime()-Date.now());if(ms===0){remaining='Expired';return}const total=Math.floor(ms/1000),m=Math.floor(total/60),s=String(total%60).padStart(2,'0');remaining=`${m}:${s}`}onMount(()=>{QRCode.toDataURL(invoice.bolt11,{width:220,margin:1,color:{dark:'#12251f',light:'#ffffff'}}).then(v=>qr=v);update();const t=setInterval(update,1000);return()=>clearInterval(t)});async function copy(){await navigator.clipboard?.writeText(invoice.bolt11);copied=true;setTimeout(()=>copied=false,1800)}</script><div class="invoice-panel"><div class="invoice-panel-head"><span class="eyebrow">BLINK LIGHTNING INVOICE</span><span class:paid={invoice.status==='paid'} class:expired={invoice.status==='expired'||remaining==='Expired'} class="invoice-state">{invoice.status==='paid'?'Paid':invoice.status==='expired'||remaining==='Expired'?'Expired':'Awaiting payment'}</span></div>{#if qr}<img class="invoice-qr" src={qr} alt="Lightning invoice QR code"/>{:else}<div class="invoice-qr-placeholder">Generating QR…</div>{/if}<strong class="invoice-amount">{invoice.amountSats.toLocaleString()} sats</strong><div class="invoice-countdown">{invoice.status==='paid'?'Payment confirmed':remaining==='Expired'?'This invoice has expired':`Expires in ${remaining}`}</div><div class="invoice-string"><code>{invoice.bolt11}</code><button type="button" class="copy-button" aria-label="Copy invoice" onclick={copy}><i class="fa-regular fa-copy"></i>{copied?'Copied':'Copy'}</button></div>{#if invoice.status==='paid'}<p class="invoice-success"><i class="fa-solid fa-circle-check"></i> Blink payment received.</p>{:else if remaining==='Expired'}<p class="invoice-expired"><i class="fa-solid fa-clock"></i> Create a new invoice to try again.</p>{/if}</div>
